a.c('public_function_family','PublicFunctionDefinition<K>','One versioned closed family shared by SDK/CLI owns operation identities/variants, request/result/refusal, authority/effect class, operation-indexed binding, capabilities and adapter coordinates; source-blind classification separates public read, runtime mutation/attestation, install/config, release and internal-only.',[g(1,109,116)])
